public class MemoryLeakDemo {
    // A static collection acting as a classic memory leak source
    private static final List<byte[]> leakyCache = new ArrayList<>();

    public void consumeMemory() {
        // Continuously allocate large arrays and never release references
        while (true) {
            leakyCache.add(new byte[1024 * 1024]); // 1 MB allocation
            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public static void main(String[] args) {
        // Pass JVM flags: -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/var/log/java/dumps
        new MemoryLeakDemo().consumeMemory();
    }
}
